// Standard binary search — closed interval [lo, hi]
function binarySearch(arr, target) {
  let lo = 0, hi = arr.length - 1;
  while (lo <= hi) {
    const mid = lo + Math.floor((hi - lo) / 2); // overflow-safe
    if (arr[mid] === target) return mid;
    if (arr[mid] < target) lo = mid + 1; // target in right half
    else hi = mid - 1;                   // target in left half
  }
  return -1; // not found
}

// Lower bound — leftmost index where arr[i] >= target
// (equivalent to Python's bisect_left)
function lowerBound(arr, target) {
  let lo = 0, hi = arr.length;
  while (lo < hi) {                        // half-open [lo, hi)
    const mid = lo + Math.floor((hi - lo) / 2);
    if (arr[mid] < target) lo = mid + 1;   // target must be to the right
    else hi = mid;                         // mid might be the answer, keep it
  }
  return lo; // insertion point
}

// Upper bound — leftmost index where arr[i] > target
function upperBound(arr, target) {
  let lo = 0, hi = arr.length;
  while (lo < hi) {
    const mid = lo + Math.floor((hi - lo) / 2);
    if (arr[mid] <= target) lo = mid + 1;
    else hi = mid;
  }
  return lo;
}

const arr = [1, 3, 5, 7, 9, 11, 13];
console.log(binarySearch(arr, 7));    // 3
console.log(binarySearch(arr, 6));    // -1

const arr2 = [1, 2, 2, 2, 3, 4];
console.log(lowerBound(arr2, 2)); // 1 (first 2)
console.log(upperBound(arr2, 2)); // 4 (first element > 2)
console.log(upperBound(arr2, 2) - lowerBound(arr2, 2)); // 3 (count of 2s)

