// ── Template: binary search on the answer ──────────────────────
// Many problems reduce to: find the minimum x such that condition(x) is true
// The 'array' is the implicit range [lo, hi] of possible answers.

function minSpeedToArrive(tasks, hoursLimit) {
  // Is it possible to complete all tasks at speed 'speed'?
  function feasible(speed) {
    let hours = 0;
    for (let i = 0; i < tasks.length - 1; i++) {
      hours += Math.ceil(tasks[i] / speed); // wait for next whole hour
    }
    hours += tasks[tasks.length - 1] / speed; // last task: exact fraction
    return hours <= hoursLimit;
  }

  let lo = 1, hi = 10_000_000;
  while (lo < hi) {
    const mid = lo + Math.floor((hi - lo) / 2);
    if (feasible(mid)) hi = mid; // mid works — try smaller
    else lo = mid + 1;           // too slow — need more speed
  }
  return feasible(lo) ? lo : -1;
}

